import { StrictMode, useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';

const API_BASE = import.meta.env.VITE_API_URL || (typeof window !== 'undefined' ? `${window.location.protocol}//${window.location.hostname}:5000/api/v1` : 'http://localhost:5000/api/v1');
const products = [];
const API_ORIGIN = API_BASE.replace(/\/api\/v1\/?$/, '');
const MEDIA_ORIGIN = typeof window !== 'undefined' && ['localhost', '127.0.0.1', '0.0.0.0'].includes(new URL(API_ORIGIN).hostname) ? `${window.location.protocol}//${window.location.hostname}:5000` : API_ORIGIN;

function assetUrl(url) {
  if (!url) return '';
  try {
    const parsed = new URL(url, MEDIA_ORIGIN);
    // In local development Vite serves /uploads from the same origin as the
    // WebView page. Using that origin also avoids Android/Expo firewall issues
    // when the API port is reachable differently from the web port.
    if (typeof window !== 'undefined' && parsed.pathname.startsWith('/uploads/')) return `${window.location.origin}${parsed.pathname}${parsed.search}`;
    if (['localhost', '127.0.0.1', '0.0.0.0'].includes(parsed.hostname)) return `${MEDIA_ORIGIN}${parsed.pathname}${parsed.search}`;
    return parsed.toString();
  } catch { return `${MEDIA_ORIGIN}${url.startsWith('/') ? url : `/${url}`}`; }
}

function ImageUploadControl({ accessToken, label, multiple = false, onUploaded }) {
  const [uploading, setUploading] = useState(false);
  async function upload(event) {
    const files = [...event.target.files];
    event.target.value = '';
    if (!files.length) return;
    setUploading(true);
    try {
      const urls = [];
      for (const file of files) {
        if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) throw new Error('Use JPG, PNG or WebP images.');
        if (file.size > 1.5 * 1024 * 1024) throw new Error('Each image must be smaller than 1.5 MB.');
        const dataUrl = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(new Error('Unable to read image.')); reader.readAsDataURL(file); });
        const response = await fetch(`${API_BASE}/uploads/image`, { method: 'POST', headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ dataUrl }) });
        const data = await response.json();
        if (!response.ok) throw new Error(data.error?.message || 'Image upload failed.');
        urls.push(assetUrl(data.url));
      }
      await onUploaded(urls);
    } catch (error) { window.alert(error.message); }
    finally { setUploading(false); }
  }
  return <label className="image-upload-control"><span>{uploading ? 'Uploading…' : label}</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple={multiple} onChange={upload} disabled={uploading} /></label>;
}

function useNativeBack(onBack) {
  useEffect(() => {
    const goBack = () => { onBack?.(); };
    window.__gatedcartNativeBack = goBack;
    window.ReactNativeWebView?.postMessage(JSON.stringify({ canGoBack: Boolean(onBack) }));
    return () => { if (window.__gatedcartNativeBack === goBack) delete window.__gatedcartNativeBack; };
  }, [onBack]);
}

async function readApiResponse(response) {
  const text = await response.text();
  try { return JSON.parse(text); } catch { return { error: { message: text || `Request failed (${response.status})` } }; }
}

function sellerPresentation(seller, index) {
  const name = seller.businessName || seller.sellerName;
  const logoMap = { 'Home Foods': 'bowl', 'Sweet Home Bakery': 'cake', 'Fashion Corner': 'hanger', 'Fresh Basket': 'basket', 'Sri Lakshmi Supermarket': 'cart', 'Fresh Vegetables': 'leaf' };
  const colorMap = { 'Home Foods': 'coral', 'Sweet Home Bakery': 'gold', 'Fashion Corner': 'blue', 'Fresh Basket': 'green', 'Sri Lakshmi Supermarket': 'violet', 'Fresh Vegetables': 'mint' };
  return { ...seller, name, detail: seller.description || (seller.sellerType === 'APARTMENT' ? 'Local community seller' : 'Serving your community'), initials: name.split(' ').map(word => word[0]).join('').slice(0, 2), logo: logoMap[name] || ['bowl', 'basket', 'leaf'][index % 3], color: colorMap[name] || ['coral', 'green', 'mint'][index % 3], rating: seller.rating || 'New', time: seller.deliveryEnabled === false ? 'Pickup available' : 'Delivery available' };
}

