function Logo() {
  function toggleDashboardMenu() { const sidebars = document.querySelectorAll('.dashboard-side'); sidebars.forEach(sidebar => sidebar.classList.toggle('mobile-menu-visible')); const closeMenu = event => { if (event.target.closest?.('.dashboard-side') && event.target.closest('button')) { sidebars.forEach(sidebar => sidebar.classList.remove('mobile-menu-visible')); document.removeEventListener('click', closeMenu); } else if (!event.target.closest?.('.dashboard-menu-button') && !event.target.closest?.('.dashboard-side')) { sidebars.forEach(sidebar => sidebar.classList.remove('mobile-menu-visible')); document.removeEventListener('click', closeMenu); } }; document.addEventListener('click', closeMenu); }
  function navigateDashboard(label) { const button = [...document.querySelectorAll('.dashboard-side button')].find(item => item.textContent.trim().toLowerCase().includes(label.toLowerCase())); if (button) button.click(); else document.querySelector('.dashboard-menu-button')?.click(); }
  return <><button className="dashboard-menu-button" onClick={toggleDashboardMenu} aria-label="Expand or collapse navigation">☰ <span>Menu</span></button><div className="brand brand-logo"><GatedCartLogo /></div><nav className="dashboard-mobile-nav"><button onClick={() => navigateDashboard('Orders')}>Orders</button><button onClick={() => navigateDashboard('Overview')}>Overview</button><button onClick={() => navigateDashboard('Products')}>Products</button><button onClick={() => navigateDashboard('Settings')}>Settings</button></nav></>;
}

