function AdminWorkspaceLegacy({ token, onLogout }) {
  const [tab, setTab] = useState('overview'); const [dashboard, setDashboard] = useState({ users: 0, sellers: 0, apartments: 0, ordersToday: 0, pendingAds: 0 }); const [users, setUsers] = useState([]); const [apartments, setApartments] = useState([]); const [sellers, setSellers] = useState([]); const [orders, setOrders] = useState([]); const [message, setMessage] = useState(''); const [apartmentForm, setApartmentForm] = useState({ name: '', city: '' }); const [blockNames, setBlockNames] = useState({}); const [flatForms, setFlatForms] = useState({});
  const headers = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
  async function loadTab(nextTab = tab) { setMessage(''); try { if (nextTab === 'overview') setDashboard(await fetch(`${API_BASE}/admin/dashboard`, { headers }).then(response => response.json())); if (nextTab === 'customers') setUsers(await fetch(`${API_BASE}/admin/users`, { headers }).then(response => response.json())); if (nextTab === 'apartments') setApartments(await fetch(`${API_BASE}/admin/apartments`, { headers }).then(response => response.json())); if (nextTab === 'sellers') setSellers(await fetch(`${API_BASE}/admin/sellers`, { headers }).then(response => response.json())); if (nextTab === 'orders') setOrders(await fetch(`${API_BASE}/admin/orders`, { headers }).then(response => response.json())); } catch (error) { setMessage(error.message || 'Unable to load admin data.'); } }
  useEffect(() => { void loadTab(tab); }, [tab]);
  function selectTab(nextTab) { setTab(nextTab); }
  async function createApartment(event) { event.preventDefault(); const response = await fetch(`${API_BASE}/admin/apartments`, { method: 'POST', headers, body: JSON.stringify({ ...apartmentForm, state: 'Telangana', hasBlocks: true, hasPredefinedFlats: true }) }); const data = await response.json(); if (response.ok) { setApartmentForm({ name: '', city: '' }); setMessage('Apartment created.'); void loadTab('apartments'); } else setMessage(data.error?.message || 'Unable to create apartment.'); }
  async function addBlock(apartmentId) { const response = await fetch(`${API_BASE}/admin/apartments/${apartmentId}/blocks`, { method: 'POST', headers, body: JSON.stringify({ name: blockNames[apartmentId] }) }); if (response.ok) { setBlockNames(current => ({ ...current, [apartmentId]: '' })); setMessage('Block added.'); void loadTab('apartments'); } else setMessage('Unable to add block.'); }
  async function addFlat(blockId) { const response = await fetch(`${API_BASE}/admin/blocks/${blockId}/flats`, { method: 'POST', headers, body: JSON.stringify({ number: flatForms[blockId] }) }); if (response.ok) { setFlatForms(current => ({ ...current, [blockId]: '' })); setMessage('Flat added.'); void loadTab('apartments'); } else setMessage('Unable to add flat.'); }
  async function updateUser(user, nextRole) { const roles = nextRole === 'CUSTOMER' ? ['CUSTOMER'] : nextRole === 'GLOBAL_ADMIN' ? ['GLOBAL_ADMIN'] : ['CUSTOMER', nextRole]; const response = await fetch(`${API_BASE}/admin/users/${user.id}`, { method: 'PATCH', headers, body: JSON.stringify({ roles }) }); if (response.ok) { setMessage('User role updated.'); void loadTab('customers'); } else setMessage('Unable to update user role.'); }
  async function toggleUser(user) { const response = await fetch(`${API_BASE}/admin/users/${user.id}`, { method: 'PATCH', headers, body: JSON.stringify({ isActive: !user.isActive }) }); if (response.ok) { setMessage('User status updated.'); void loadTab('customers'); } else { const data = await response.json(); setMessage(data.error?.message || 'Unable to update user status.'); } }
  async function updateSeller(seller, status) { const response = await fetch(`${API_BASE}/sellers/${seller.id}/status`, { method: 'PATCH', headers, body: JSON.stringify({ status }) }); if (response.ok) { setMessage('Seller status updated.'); void loadTab('sellers'); } else setMessage('Unable to update seller.'); }
  async function updateOrder(order, status) { const response = await fetch(`${API_BASE}/orders/${order.id}/status`, { method: 'PATCH', headers, body: JSON.stringify({ status, note: 'Updated by Global Admin' }) }); if (response.ok) { setMessage('Order status updated.'); void loadTab('orders'); } else setMessage('Unable to update order status.'); }
  const nav = [['overview', 'Overview'], ['customers', 'Customers'], ['apartments', 'Apartments'], ['sellers', 'Sellers'], ['orders', 'Orders'], ['settings', 'Settings']];
  return <div className="dashboard-shell"><header className="dashboard-nav"><Logo /><div className="dashboard-nav-links"><span className="active">Global admin</span><span>Reports</span><span>Settings</span></div><div className="profile-chip"><span>AD</span><b>Global Admin</b></div><button className="admin-portal-logout" onClick={onLogout}>Sign out</button></header><div className="dashboard-layout"><aside className="dashboard-side"><div className="side-label">WORKSPACE</div>{nav.map(([key, label]) => <button key={key} className={tab === key ? 'selected' : ''} onClick={() => selectTab(key)}>{label}</button>)}</aside><main className="dashboard-main"><div className="dashboard-heading"><div><p className="eyebrow">PLATFORM CONTROL</p><h1>{tab === 'overview' ? 'Good morning, Admin' : `${nav.find(item => item[0] === tab)?.[1]} management`}</h1><p>Manage live marketplace data and configuration.</p></div></div>{message && <p className="dashboard-message">{message}</p>}{tab === 'overview' && <><div className="metric-grid">{[['Total users', dashboard.users], ['Active sellers', dashboard.sellers], ['Orders today', dashboard.ordersToday], ['Pending approvals', dashboard.pendingAds]].map(([label, value]) => <div className="metric-card" key={label}><span>{label}</span><strong>{value}</strong><small>Live database value</small></div>)}</div><section className="dashboard-panel"><h2>Global Admin controls</h2><p className="orders-copy">Use the sidebar to manage customers, communities, sellers, orders and platform settings.</p></section></>}{tab === 'customers' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Customers and users</h2><span className="menu-count">{users.length} users</span></div><div className="admin-user-list">{users.map(user => <div className="admin-user-row" key={user.id}><div><strong>{user.name || 'Unnamed user'}</strong><small>{user.phone} · {user.roles?.map(item => item.role.code).join(', ')}</small></div><select value={user.roles?.find(item => item.role.code !== 'CUSTOMER')?.role.code || 'CUSTOMER'} onChange={event => updateUser(user, event.target.value)}><option value="CUSTOMER">Customer</option><option value="APARTMENT_SELLER">Apartment seller</option><option value="OUTSIDE_SELLER">Outside seller</option><option value="DELIVERY_BOY">Delivery boy</option><option value="GLOBAL_ADMIN">Global admin</option></select><button onClick={() => toggleUser(user)}>{user.isActive ? 'Deactivate' : 'Activate'}</button></div>)}</div></section>}{tab === 'apartments' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Apartments, blocks and flats</h2><span className="menu-count">{apartments.length} apartments</span></div><form className="quick-product-form" onSubmit={createApartment}><input value={apartmentForm.name} onChange={event => setApartmentForm(current => ({ ...current, name: event.target.value }))} placeholder="Apartment name" required /><input value={apartmentForm.city} onChange={event => setApartmentForm(current => ({ ...current, city: event.target.value }))} placeholder="City" required /><button className="primary-button">Add apartment</button></form><div className="admin-apartment-list">{apartments.map(apartment => <article className="admin-apartment-row admin-apartment-detail" key={apartment.id}><div><strong>{apartment.name}</strong><small>{apartment.city || '—'} · {apartment.isActive ? 'Active' : 'Inactive'}</small></div><div className="admin-nested-controls"><form onSubmit={event => { event.preventDefault(); void addBlock(apartment.id); }}><input value={blockNames[apartment.id] || ''} onChange={event => setBlockNames(current => ({ ...current, [apartment.id]: event.target.value }))} placeholder="New block" required /><button>Add block</button></form>{apartment.blocks?.map(block => <div className="nested-row" key={block.id}><span>{block.name} · {block.flats?.length || 0} flats</span><form onSubmit={event => { event.preventDefault(); void addFlat(block.id); }}><input value={flatForms[block.id] || ''} onChange={event => setFlatForms(current => ({ ...current, [block.id]: event.target.value }))} placeholder="Flat no." required /><button>Add flat</button></form></div>)}</div></article>)}</div></section>}{tab === 'sellers' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Seller approvals and status</h2><span className="menu-count">{sellers.length} sellers</span></div><div className="admin-seller-list">{sellers.map(seller => <div className="admin-seller-row" key={seller.id}><div><strong>{seller.businessName || seller.sellerName}</strong><small>{seller.sellerType} · {seller.apartment?.name || 'Outside delivery areas'}</small></div><select value={seller.status} onChange={event => updateSeller(seller, event.target.value)}><option value="PENDING">Pending</option><option value="APPROVED">Approved</option><option value="REJECTED">Rejected</option><option value="SUSPENDED">Suspended</option><option value="INACTIVE">Inactive</option></select></div>)}</div></section>}{tab === 'orders' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>All marketplace orders</h2><span className="menu-count">{orders.length} orders</span></div><div className="admin-order-list">{orders.map(order => <div className="admin-order-row" key={order.id}><div><strong>{order.orderNumber}</strong><small>{order.customer?.name || order.customer?.phone} · {order.seller?.businessName || order.seller?.sellerName} · {order.apartment?.name || 'No apartment'}</small></div><select value={order.status} onChange={event => updateOrder(order, event.target.value)}><option value={order.status}>{order.status.replaceAll('_', ' ')}</option><option value="ACCEPTED">Accepted</option><option value="PREPARING">Preparing</option><option value="READY_FOR_PICKUP">Ready for pickup</option><option value="DELIVERED">Delivered</option><option value="COMPLETED">Completed</option><option value="CANCELLED">Cancelled</option></select><strong>₹{Number(order.total).toFixed(2)}</strong></div>)}</div></section>}{tab === 'settings' && <AdminControls />}</main></div></div>;
}

function AdminHomePromotions({ token }) {
  const [items, setItems] = useState([]); const [message, setMessage] = useState('');
  async function load() { const response = await fetch(`${API_BASE}/admin/home-promotions`, { headers: { Authorization: `Bearer ${token}` } }); const data = await response.json(); if (response.ok) setItems(Array.isArray(data) ? data : []); else setMessage(data.error?.message || 'Unable to load home promotions.'); }
  useEffect(() => { if (token) void load(); }, [token]);
  async function upload(urls) { const response = await fetch(`${API_BASE}/admin/home-promotions`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ imageUrls: urls }) }); const data = await response.json(); if (response.ok) { setItems(current => [...data, ...current]); setMessage(`${urls.length} home image${urls.length === 1 ? '' : 's'} added.`); } else setMessage(data.error?.message || 'Unable to save home promotions.'); }
  function localDateValue(value) { return value ? new Date(value).toISOString().slice(0, 16) : ''; }
  async function update(item, body) { const response = await fetch(`${API_BASE}/admin/home-promotions/${item.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify(body) }); const data = await response.json(); if (response.ok) setItems(current => current.map(entry => entry.id === item.id ? data : entry)); else setMessage(data.error?.message || 'Unable to update home promotion.'); }
  async function remove(item) { if (!window.confirm('Delete this home promotion?')) return; const response = await fetch(`${API_BASE}/admin/home-promotions/${item.id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } }); if (response.ok) setItems(current => current.filter(entry => entry.id !== item.id)); else setMessage('Unable to delete home promotion.'); }
  return <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><div><p className="eyebrow">HOME PAGE</p><h2>Home carousel images</h2></div><span className="menu-count">{items.length} images</span></div><p className="orders-copy">Upload images for the top home carousel. Set activation and expiry separately for every image.</p><div className="quick-product-form"><ImageUploadControl accessToken={token} label="Upload carousel images" multiple onUploaded={upload} /></div><div className="home-promotion-admin-list">{items.map(item => <div className="home-promotion-admin-row" key={item.id}><img src={assetUrl(item.imageUrl || item.imageUrls?.[0])} alt="Home promotion" /><div><strong>{item.status === 'APPROVED' ? 'Active' : 'Inactive'}</strong><label>Display until<input type="datetime-local" value={localDateValue(item.endAt)} onChange={event => update(item, { endAt: event.target.value || null })} /></label><small>{item.endAt ? `Until ${new Date(item.endAt).toLocaleString()}` : 'No end date'}</small></div><button onClick={() => update(item, { isActive: item.status !== 'APPROVED' })}>{item.status === 'APPROVED' ? 'Deactivate' : 'Activate'}</button><button className="danger-text" onClick={() => remove(item)}>Delete</button></div>)}</div>{message && <small className="dashboard-message">{message}</small>}</section>;
}

function AdminSellerApprovalPanel({ token, onBack }) {
  const [sellers, setSellers] = useState([]); const [message, setMessage] = useState('');
  async function load() { const response = await fetch(`${API_BASE}/admin/sellers`, { headers: { Authorization: `Bearer ${token}` } }); const data = await response.json(); if (response.ok) setSellers(Array.isArray(data) ? data.map(item => ({ ...item, sellerName: `${item.sellerName} · Phone: ${item.user?.phone || 'Not provided'}` })) : []); else setMessage(data.error?.message || 'Unable to load seller approvals.'); }
  useEffect(() => { void load(); }, [token]);
  async function updateStatus(seller, status) { const response = await fetch(`${API_BASE}/sellers/${seller.id}/status`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ status }) }); const data = await response.json(); if (response.ok) { setSellers(current => current.map(item => item.id === seller.id ? { ...item, status: data.status } : item)); setMessage(`${seller.businessName || seller.sellerName} is now ${status}.`); } else setMessage(data.error?.message || 'Unable to update seller status.'); }
  return <div className="dashboard-shell"><header className="dashboard-nav"><Logo /><div className="profile-chip"><span>AD</span><b>Seller approvals</b></div><button className="admin-portal-logout" onClick={onBack}>Back to dashboard</button></header><main className="dashboard-main seller-approval-page"><div className="dashboard-heading"><div><p className="eyebrow">SELLER MANAGEMENT</p><h1>Seller approval requests</h1><p>Review the complete request and delivery details before approving a seller.</p></div></div>{message && <p className="dashboard-message">{message}</p>}<section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Pending and approved sellers</h2><span className="menu-count">{sellers.filter(item => item.status === 'PENDING').length} pending</span></div><div className="admin-seller-approval-list">{sellers.length ? sellers.map(seller => { const association = seller.user?.apartments?.find(item => item.isPrimary) || seller.user?.apartments?.[0]; return <details className="admin-seller-approval-card" key={seller.id} open={seller.status === 'PENDING'}><summary><div><strong>{seller.businessName || seller.sellerName}</strong><small>{seller.sellerType === 'APARTMENT' ? 'Community seller' : 'Outside seller'} · {seller.status}</small></div><span className={`status status-${seller.status.toLowerCase()}`}>{seller.status}</span></summary><div className="seller-request-details"><div><span>Seller name</span><strong>{seller.sellerName}</strong></div><div><span>Business name</span><strong>{seller.businessName || 'Not provided'}</strong></div><div><span>Request type</span><strong>{seller.sellerType === 'APARTMENT' ? 'Community seller' : 'Outside seller'}</strong></div><div><span>Community</span><strong>{seller.apartment?.name || association?.apartment?.name || 'Not selected'}</strong></div><div><span>Block</span><strong>{association?.block?.name || 'Not provided'}</strong></div><div><span>Flat</span><strong>{association?.flat?.number || association?.manualFlatNumber || 'Not provided'}</strong></div><div className="seller-request-description"><span>Request description</span><strong>{seller.description || 'No description provided'}</strong></div><div className="seller-request-description"><span>Outside delivery communities</span><strong>{seller.deliveryAreas?.length ? seller.deliveryAreas.map(area => `${area.apartment?.name}${area.isApproved ? ' (approved)' : ' (pending)'}`).join(', ') : 'Not applicable'}</strong></div></div><div className="seller-approval-actions"><select value={seller.status} onChange={event => updateStatus(seller, event.target.value)}><option value="PENDING">Pending</option><option value="APPROVED">Approve</option><option value="REJECTED">Reject</option><option value="SUSPENDED">Suspend</option><option value="INACTIVE">Deactivate</option></select></div></details>; }) : <p className="empty-panel-copy">No seller requests available.</p>}</div></section></main></div>;
}

function AdminWorkspace({ token, onLogout }) {
  const [tab, setTab] = useState('overview'); const [data, setData] = useState([]); const [metrics, setMetrics] = useState({}); const [message, setMessage] = useState(''); const [apartmentForm, setApartmentForm] = useState({ name: '', city: '' }); const [blockDrafts, setBlockDrafts] = useState({}); const [blockEdits, setBlockEdits] = useState({});
  const headers = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
  async function load(nextTab = tab) { setMessage(''); const endpoint = nextTab === 'overview' ? '/admin/dashboard' : nextTab === 'customers' ? '/admin/users' : nextTab === 'apartments' ? '/admin/apartments' : nextTab === 'sellers' ? '/admin/sellers' : nextTab === 'orders' ? '/admin/orders' : null; if (!endpoint) return; const response = await fetch(`${API_BASE}${endpoint}`, { headers }); const result = await response.json(); if (!response.ok) { setMessage(result.error?.message || 'Unable to load data.'); return; } if (nextTab === 'overview') setMetrics(result); else setData(Array.isArray(result) ? result : []); }
  useEffect(() => { void load(tab); }, [tab]);
  useEffect(() => {
    const goBack = () => { if (tab !== 'overview') setTab('overview'); };
    window.__gatedcartNativeBack = goBack;
    window.ReactNativeWebView?.postMessage(JSON.stringify({ canGoBack: tab !== 'overview' }));
    return () => { if (window.__gatedcartNativeBack === goBack) delete window.__gatedcartNativeBack; };
  }, [tab]);
  useEffect(() => {
    function openMetric(event) {
      const card = event.target.closest?.('.metric-card');
      if (!card) return;
      const label = card.querySelector('span')?.textContent;
      if (label === 'Total users') setTab('customers');
      if (label === 'Active sellers' || label === 'Pending approvals') setTab('sellers');
      if (label === 'Orders today') setTab('orders');
    }
    document.addEventListener('click', openMetric);
    return () => document.removeEventListener('click', openMetric);
  }, []);
  if (tab === 'sellers') return <AdminSellerApprovalPanel token={token} onBack={() => setTab('overview')} />;
  async function createApartment(event) { event.preventDefault(); const response = await fetch(`${API_BASE}/admin/apartments`, { method: 'POST', headers, body: JSON.stringify({ ...apartmentForm, state: 'Telangana', hasBlocks: true, hasPredefinedFlats: false }) }); if (response.ok) { setApartmentForm({ name: '', city: '' }); setMessage('Apartment created.'); void load('apartments'); } else setMessage('Unable to create apartment.'); }
  async function createBlock(event, apartmentId) { event.preventDefault(); const response = await fetch(`${API_BASE}/admin/apartments/${apartmentId}/blocks`, { method: 'POST', headers, body: JSON.stringify({ name: blockDrafts[apartmentId] }) }); if (response.ok) { setBlockDrafts(current => ({ ...current, [apartmentId]: '' })); setMessage('Block created.'); void load('apartments'); } else setMessage('Unable to create block.'); }
  async function updateBlock(block, isActive = block.isActive, name = blockEdits[block.id] ?? block.name) { const response = await fetch(`${API_BASE}/admin/blocks/${block.id}`, { method: 'PATCH', headers, body: JSON.stringify({ name, isActive }) }); if (response.ok) { setMessage('Block updated.'); void load('apartments'); } else setMessage('Unable to update block.'); }
  async function updateApartment(apartment) { const response = await fetch(`${API_BASE}/admin/apartments/${apartment.id}`, { method: 'PATCH', headers, body: JSON.stringify({ isActive: !apartment.isActive }) }); if (response.ok) { setMessage('Apartment status updated.'); void load('apartments'); } }
  async function updateUser(user, role) { const roles = role === 'CUSTOMER' ? ['CUSTOMER'] : role === 'GLOBAL_ADMIN' ? ['GLOBAL_ADMIN'] : ['CUSTOMER', role]; const response = await fetch(`${API_BASE}/admin/users/${user.id}`, { method: 'PATCH', headers, body: JSON.stringify({ roles }) }); if (response.ok) { setMessage('User role updated.'); void load('customers'); } }
  async function updateSeller(seller, status) { const response = await fetch(`${API_BASE}/sellers/${seller.id}/status`, { method: 'PATCH', headers, body: JSON.stringify({ status }) }); if (response.ok) { setMessage('Seller status updated.'); void load('sellers'); } }
  async function updateOrder(order, status) { const response = await fetch(`${API_BASE}/orders/${order.id}/status`, { method: 'PATCH', headers, body: JSON.stringify({ status, note: 'Updated by Global Admin' }) }); if (response.ok) { setMessage('Order status updated.'); void load('orders'); } }
  const nav = [['overview', 'Overview'], ['customers', 'Customers'], ['apartments', 'Apartments'], ['sellers', 'Sellers'], ['orders', 'Orders'], ['settings', 'Settings']];
  return <div className="dashboard-shell"><header className="dashboard-nav"><Logo /><div className="dashboard-nav-links"><span className="active">Global admin</span><span>Reports</span><span>Settings</span></div><div className="profile-chip"><span>AD</span><b>Global Admin</b></div><button className="admin-portal-logout" onClick={onLogout}>Sign out</button></header><div className="dashboard-layout"><aside className="dashboard-side"><div className="side-label">WORKSPACE</div>{nav.map(([key, label]) => <button key={key} className={tab === key ? 'selected' : ''} onClick={() => { setTab(key); setData([]); }}>{label}</button>)}</aside><main className="dashboard-main"><div className="dashboard-heading"><div><p className="eyebrow">PLATFORM CONTROL</p><h1>{tab === 'overview' ? 'Good morning, Admin' : `${nav.find(item => item[0] === tab)?.[1]} management`}</h1><p>Manage live marketplace data and configuration.</p></div></div>{message && <p className="dashboard-message">{message}</p>}{tab === 'overview' && <div className="metric-grid">{[['Total users', metrics.users], ['Active sellers', metrics.sellers], ['Orders today', metrics.ordersToday], ['Pending approvals', metrics.pendingAds]].map(([label, value]) => <div className="metric-card" key={label}><span>{label}</span><strong>{value ?? 0}</strong><small>Live database value</small></div>)}</div>}{tab === 'customers' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Customers and users</h2><span>{data.length} users</span></div><div className="admin-user-list">{data.map(user => <div className="admin-user-row" key={user.id}><div><strong>{user.name || 'Unnamed user'}</strong><small>{user.phone} · {user.roles?.map(item => item.role.code).join(', ')}</small></div><select value={user.roles?.find(item => item.role.code !== 'CUSTOMER')?.role.code || 'CUSTOMER'} onChange={event => updateUser(user, event.target.value)}><option value="CUSTOMER">Customer</option><option value="APARTMENT_SELLER">Apartment seller</option><option value="OUTSIDE_SELLER">Outside seller</option><option value="DELIVERY_BOY">Delivery boy</option><option value="GLOBAL_ADMIN">Global admin</option></select></div>)}</div></section>}{tab === 'apartments' && <section className="dashboard-panel admin-resource-panel apartment-tree-panel"><div className="panel-heading"><h2>Apartments and blocks</h2><span>{data.length} apartments</span></div><form className="apartment-create-form" onSubmit={createApartment}><input value={apartmentForm.name} onChange={event => setApartmentForm(current => ({ ...current, name: event.target.value }))} placeholder="Apartment name" required /><input value={apartmentForm.city} onChange={event => setApartmentForm(current => ({ ...current, city: event.target.value }))} placeholder="City" required /><button className="primary-button">Add apartment</button></form><div className="apartment-tree">{data.map(apartment => <details className="apartment-node" key={apartment.id}><summary><span><strong>{apartment.name}</strong><small>{apartment.city || '—'} · {apartment.isActive ? 'Active' : 'Inactive'}</small></span><button type="button" onClick={event => { event.preventDefault(); void updateApartment(apartment); }}>{apartment.isActive ? 'Deactivate' : 'Activate'}</button></summary><form className="block-create-form" onSubmit={event => createBlock(event, apartment.id)}><input value={blockDrafts[apartment.id] || ''} onChange={event => setBlockDrafts(current => ({ ...current, [apartment.id]: event.target.value }))} placeholder="New block name" required /><button>Add block</button></form><div className="block-list">{(apartment.blocks || []).map(block => <div className="block-node" key={block.id}><span className="block-branch">↳</span><input value={blockEdits[block.id] ?? block.name} onChange={event => setBlockEdits(current => ({ ...current, [block.id]: event.target.value }))} /><button type="button" onClick={() => updateBlock(block)}>Save</button><button type="button" onClick={() => updateBlock(block, !block.isActive)}>{block.isActive ? 'Deactivate' : 'Activate'}</button></div>)}</div></details>)}</div></section>}{tab === 'sellers' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Seller approvals</h2><span>{data.length} sellers</span></div>{data.map(seller => <div className="admin-seller-row" key={seller.id}><div><strong>{seller.businessName || seller.sellerName}</strong><small>{seller.sellerType} · {seller.apartment?.name || 'Outside seller'}</small></div><select value={seller.status} onChange={event => updateSeller(seller, event.target.value)}><option value="PENDING">Pending</option><option value="APPROVED">Approved</option><option value="REJECTED">Rejected</option><option value="SUSPENDED">Suspended</option><option value="INACTIVE">Inactive</option></select></div>)}</section>}{tab === 'orders' && <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><h2>Marketplace orders</h2><span>{data.length} orders</span></div>{data.map(order => <div className="admin-order-row" key={order.id}><div><strong>{order.orderNumber}</strong><small>{order.customer?.name || order.customer?.phone} · {order.seller?.businessName || order.seller?.sellerName}</small></div><select value={order.status} onChange={event => updateOrder(order, event.target.value)}><option value={order.status}>{order.status.replaceAll('_', ' ')}</option><option value="ACCEPTED">Accepted</option><option value="PREPARING">Preparing</option><option value="READY_FOR_PICKUP">Ready for pickup</option><option value="DELIVERED">Delivered</option><option value="COMPLETED">Completed</option><option value="CANCELLED">Cancelled</option></select><strong>₹{Number(order.total).toFixed(2)}</strong></div>)}</section>}{tab === 'settings' && <AdminControls />}</main></div></div>;
}

function AdminPortal() {
  const [token, setToken] = useState(() => window.localStorage.getItem('gatedcart_admin_access_token'));
  if (!token) return <AdminLoginScreen onAuthenticated={nextToken => { window.localStorage.setItem('gatedcart_admin_access_token', nextToken); setToken(nextToken); }} />;
  return <AdminWorkspace token={token} onLogout={() => { window.localStorage.removeItem('gatedcart_admin_access_token'); setToken(null); }} />;
}

function Topbar({ onNavigate, onLogout, user, cartCount = 0, onCart }) {
  const apartmentName = user?.apartments?.find(item => item.isPrimary)?.apartment?.name || user?.apartment?.name || 'Your community';
  return <header className="topbar">
    <Logo />
    <div className="topbar-actions">
      <button className="location-pill"><Icon name="map" size={17} /><span><small>Delivering to</small>{apartmentName} <b>⌄</b></span></button>
      <button className="icon-button notification"><Icon name="bell" size={20} /><span /></button>
      <button className="icon-button cart-button topbar-cart-button" onClick={onCart} aria-label="Open cart"><Icon name="bag" size={20} />{cartCount > 0 && <span>{cartCount}</span>}</button>
      <button className="profile-chip" onClick={() => onNavigate('profile')}><span>{(user?.name || user?.phone || 'N').slice(0, 2).toUpperCase()}</span><b>{user?.name || 'Your profile'}</b><em>⌄</em></button>
    </div>
  </header>;
}

function BottomNav({ active = 'home', onNavigate, showSeller = false }) {
  return <nav className="bottom-nav">
    {[['home', 'Home'], ['bag', 'Orders'], ['seller', 'Seller'], ['user', 'Profile']].map(([icon, label]) => <button key={icon} className={`${active === icon ? 'active' : ''} ${icon === 'seller' && !showSeller ? 'disabled' : ''}`} disabled={icon === 'seller' && !showSeller} onClick={() => onNavigate(icon === 'bag' ? 'bag' : icon === 'user' ? 'profile' : icon === 'seller' ? 'seller' : 'home')}><Icon name={icon === 'seller' ? 'store' : icon} size={20} /><span>{label}</span></button>)}
  </nav>;
}

function CommunitySelector({ accessToken, onSelected }) {
  const [apartments, setApartments] = useState([]); const [apartmentId, setApartmentId] = useState(''); const [blockId, setBlockId] = useState(''); const [flatId, setFlatId] = useState(''); const [manualFlatNumber, setManualFlatNumber] = useState(''); const [error, setError] = useState(''); const [saving, setSaving] = useState(false);
  useEffect(() => { fetch(`${API_BASE}/apartments`, { headers: { Authorization: `Bearer ${accessToken}` } }).then(response => response.json()).then(data => { setApartments(Array.isArray(data) ? data : []); if (data[0]) setApartmentId(data[0].id); }).catch(() => setError('Unable to load apartments.')); }, [accessToken]);
  const apartment = apartments.find(item => item.id === apartmentId); const blocks = apartment?.blocks || []; const block = blocks.find(item => item.id === blockId); const flats = block?.flats || apartment?.flats || [];
  async function submit(event) { event.preventDefault(); setSaving(true); setError(''); try { const response = await fetch(`${API_BASE}/apartments/me`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` }, body: JSON.stringify({ apartmentId, blockId: blockId || null, flatId: flatId || null, manualFlatNumber: manualFlatNumber || null }) }); if (!response.ok) { const data = await response.json(); throw new Error(data.error?.message || 'Unable to save community'); } onSelected(); } catch (saveError) { setError(saveError.message); } finally { setSaving(false); } }
  return <main className="auth-screen community-screen"><div className="auth-card community-card"><Logo /><p className="eyebrow">SET UP YOUR COMMUNITY</p><h1>Where should we deliver?</h1><p className="auth-copy">Choose your apartment and home details so we can show the right sellers and delivery options.</p><form onSubmit={submit}><label className="auth-label">Apartment</label><select className="auth-input" value={apartmentId} onChange={event => { setApartmentId(event.target.value); setBlockId(''); setFlatId(''); }}>{apartments.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select>{blocks.length > 0 && <><label className="auth-label">Block</label><select className="auth-input" value={blockId} onChange={event => { setBlockId(event.target.value); setFlatId(''); }}><option value="">Select block</option>{blocks.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></>}{(flats.length > 0 || blocks.length === 0) && <><label className="auth-label">Flat number</label>{flats.length > 0 ? <select className="auth-input" value={flatId} onChange={event => setFlatId(event.target.value)}><option value="">Select flat</option>{flats.map(item => <option value={item.id} key={item.id}>{item.number}</option>)}</select> : <input className="auth-input" value={manualFlatNumber} onChange={event => setManualFlatNumber(event.target.value)} placeholder="Enter flat number" />}</>}<button className="auth-button" disabled={!apartmentId || saving}>{saving ? 'Saving…' : 'Continue to GatedCart'} <Icon name="arrow" size={16} /></button></form>{error && <p className="auth-error">{error}</p>}</div></main>;
}

