    <header className="store-header"><button className="back-button" onClick={onBack}><Icon name="back" size={21} /></button><div className="store-header-actions"><button className="icon-button"><Icon name="search" size={20} /></button><button className="icon-button"><Icon name="bag" size={20} /></button></div></header>
