function AdminResourceControls() {
  const [token, setToken] = useState(null); const [apartments, setApartments] = useState([]); const [name, setName] = useState(''); const [city, setCity] = useState(''); const [alertTitle, setAlertTitle] = useState(''); const [alertDescription, setAlertDescription] = useState(''); const [targetApartmentId, setTargetApartmentId] = useState(''); const [message, setMessage] = useState('');
  useEffect(() => { (async () => { try { const otp = await fetch(`${API_BASE}/auth/request-otp`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone: '9000000001' }) }).then(response => response.json()); const session = await fetch(`${API_BASE}/auth/verify-otp`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone: '9000000001', otp: otp.developmentOtp }) }).then(response => response.json()); setToken(session.accessToken); const data = await fetch(`${API_BASE}/admin/apartments`, { headers: { Authorization: `Bearer ${session.accessToken}` } }).then(response => response.json()); setApartments(Array.isArray(data) ? data : []); if (data[0]) setTargetApartmentId(data[0].id); } catch { setMessage('Admin resource API is unavailable; showing dashboard preview.'); } })(); }, []);
  async function createApartment(event) { event.preventDefault(); if (!token) return; const response = await fetch(`${API_BASE}/admin/apartments`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ name, city, state: 'Telangana', hasBlocks: true, hasPredefinedFlats: true }) }); const data = await response.json(); if (response.ok) { setApartments(current => [...current, data]); setName(''); setCity(''); setMessage('Apartment created. Add blocks and flats from the admin API.'); } else setMessage(data.error?.message || 'Unable to create apartment.'); }
  async function toggleApartment(apartment) { if (!token) return; const response = await fetch(`${API_BASE}/admin/apartments/${apartment.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ isActive: !apartment.isActive }) }); const data = await response.json(); if (response.ok) setApartments(current => current.map(item => item.id === apartment.id ? data : item)); }
  async function updateSellerVisibility(apartment, sellerDisplayMode) { if (!token) return; const response = await fetch(`${API_BASE}/admin/apartments/${apartment.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ sellerDisplayMode }) }); const data = await response.json(); if (response.ok) { setApartments(current => current.map(item => item.id === apartment.id ? { ...item, sellerDisplayMode: data.sellerDisplayMode } : item)); setMessage(`${apartment.name}: visibility saved.`); } else setMessage(data.error?.message || 'Unable to save seller visibility.'); }
  async function createAlert(event) { event.preventDefault(); if (!token) return; const response = await fetch(`${API_BASE}/admin/alerts`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ title: alertTitle, description: alertDescription, apartmentIds: targetApartmentId ? [targetApartmentId] : [] }) }); const data = await response.json(); if (response.ok) { setAlertTitle(''); setAlertDescription(''); setMessage(`Important alert created: ${data.title}`); } else setMessage(data.error?.message || 'Unable to create alert.'); }
  return <><section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><div><p className="eyebrow">COMMUNITY MANAGEMENT</p><h2>Apartments</h2><p>Choose seller visibility separately for each apartment.</p></div><span className="menu-count">{apartments.length} communities</span></div><form className="quick-product-form" onSubmit={createApartment}><input value={name} onChange={event => setName(event.target.value)} placeholder="Apartment name" required /><input value={city} onChange={event => setCity(event.target.value)} placeholder="City" required /><button className="primary-button" disabled={!token}>Add apartment</button></form><div className="admin-apartment-list">{apartments.slice(0, 8).map(apartment => <div className="admin-apartment-row" key={apartment.id}><div><strong>{apartment.name}</strong><small>{apartment.city || '—'} · {apartment._count?.residents ?? 0} residents · {apartment._count?.apartmentSellers ?? 0} sellers</small></div><label className="apartment-visibility-control"><span>Seller visibility</span><select value={apartment.sellerDisplayMode || 'BOTH'} onChange={event => updateSellerVisibility(apartment, event.target.value)} disabled={!token}><option value="LOCAL_ONLY">Community Sellers</option><option value="OUTSIDE_ONLY">Outside Sellers</option><option value="BOTH">Both</option></select></label><button onClick={() => toggleApartment(apartment)}>{apartment.isActive ? 'Deactivate' : 'Activate'}</button></div>)}</div>{message && <small className="dashboard-message">{message}</small>}</section><section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><div><p className="eyebrow">COMMUNICATION</p><h2>Create important alert</h2></div></div><form className="admin-alert-form" onSubmit={createAlert}><input value={alertTitle} onChange={event => setAlertTitle(event.target.value)} placeholder="Alert title" required /><textarea value={alertDescription} onChange={event => setDescription || setAlertDescription} placeholder="Description" rows={3} /><select value={targetApartmentId} onChange={event => setTargetApartmentId(event.target.value)}><option value="">All apartments</option>{apartments.map(apartment => <option value={apartment.id} key={apartment.id}>{apartment.name}</option>)}</select><button className="primary-button" disabled={!token}>Publish alert</button></form>{message && <small className="dashboard-message">{message}</small>}</section></>;
}

function DeliveryControls() {
  const [token, setToken] = useState(null); const [orders, setOrders] = useState([]); const [message, setMessage] = useState('');
  useEffect(() => { (async () => { try { const otp = await fetch(`${API_BASE}/auth/request-otp`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone: '9000000040' }) }).then(response => response.json()); const session = await fetch(`${API_BASE}/auth/verify-otp`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone: '9000000040', otp: otp.developmentOtp }) }).then(response => response.json()); setToken(session.accessToken); setOrders(await fetch(`${API_BASE}/delivery/orders`, { headers: { Authorization: `Bearer ${session.accessToken}` } }).then(response => response.json())); } catch { setMessage('Delivery API is unavailable; showing the dashboard preview.'); } })(); }, []);
  async function move(order, status) { if (!token) return; const response = await fetch(`${API_BASE}/delivery/orders/${order.id}/status`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ status }) }); if (response.ok) { setOrders(current => current.map(item => item.id === order.id ? { ...item, status } : item)); setMessage(`${order.orderNumber} moved to ${status.replaceAll('_', ' ')}.`); } else setMessage('This status transition was rejected by the server.'); }
  function nextStatus(status) { return status === 'READY_FOR_PICKUP' || status === 'ASSIGNED_TO_DELIVERY_BOY' ? 'PICKED_UP' : status === 'PICKED_UP' ? 'OUT_FOR_DELIVERY' : status === 'OUT_FOR_DELIVERY' ? 'DELIVERED' : null; }
  return <section className="dashboard-panel delivery-control-panel"><div className="panel-heading"><div><p className="eyebrow">LIVE DELIVERY QUEUE</p><h2>Assigned stops</h2></div><span className="menu-count">{orders.length} active</span></div>{orders.length ? <div className="delivery-queue">{orders.map(order => <div className="delivery-row" key={order.id}><div><strong>{order.orderNumber}</strong><small>{order.seller?.businessName} · {order.apartment?.name} · {order.flat?.number || order.block?.name || 'Home'}</small></div><span className="status status-preparing">{order.status.replaceAll('_', ' ')}</span>{nextStatus(order.status) && <button onClick={() => move(order, nextStatus(order.status))}>{nextStatus(order.status) === 'DELIVERED' ? 'Mark delivered' : `Mark ${nextStatus(order.status).replaceAll('_', ' ').toLowerCase()}`} <Icon name="arrow" size={14} /></button>}</div>)}</div> : <p className="empty-panel-copy">No active assignments in the current delivery scope.</p>}{message && <small className="dashboard-message">{message}</small>}</section>;
}

async function getAdminPortalToken() {
  const request = await fetch(`${API_BASE}/auth/request-otp`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: 'Global Admin', phone: '9493499405' }) });
  const otpData = await request.json();
  const session = await fetch(`${API_BASE}/auth/verify-otp`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone: '9493499405', otp: otpData.developmentOtp }) });
  const data = await session.json();
  if (!session.ok) throw new Error(data.error?.message || 'Admin authentication failed');
  return data.accessToken;
}

function AdminCommunityStructureControls() {
  const [token, setToken] = useState(null); const [apartments, setApartments] = useState([]); const [apartmentId, setApartmentId] = useState(''); const [blockId, setBlockId] = useState(''); const [blockName, setBlockName] = useState(''); const [flatNumber, setFlatNumber] = useState(''); const [message, setMessage] = useState('');
  async function load() { const data = await fetch(`${API_BASE}/admin/apartments`, { headers: { Authorization: `Bearer ${token}` } }).then(response => response.json()); setApartments(Array.isArray(data) ? data : []); if (!apartmentId && data[0]) setApartmentId(data[0].id); }
  useEffect(() => { getAdminPortalToken().then(nextToken => { setToken(nextToken); }).catch(() => setMessage('Admin authentication is unavailable.')); }, []);
  useEffect(() => { if (token) void load(); }, [token]);
  const apartment = apartments.find(item => item.id === apartmentId); const blocks = apartment?.blocks || [];
  async function addBlock(event) { event.preventDefault(); const response = await fetch(`${API_BASE}/admin/apartments/${apartmentId}/blocks`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ name: blockName }) }); if (response.ok) { setBlockName(''); setMessage('Block added.'); await load(); } else setMessage('Unable to add block.'); }
  async function addFlat(event) { event.preventDefault(); const response = await fetch(`${API_BASE}/admin/blocks/${blockId}/flats`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ number: flatNumber }) }); if (response.ok) { setFlatNumber(''); setMessage('Flat added.'); await load(); } else setMessage('Unable to add flat.'); }
  return <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><div><p className="eyebrow">COMMUNITY STRUCTURE</p><h2>Blocks and flats</h2></div></div><select className="admin-search-input" value={apartmentId} onChange={event => { setApartmentId(event.target.value); setBlockId(''); }}><option value="">Select apartment</option>{apartments.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select><form className="quick-product-form" onSubmit={addBlock}><input value={blockName} onChange={event => setBlockName(event.target.value)} placeholder="New block or tower" required /><button className="primary-button" disabled={!token || !apartmentId}>Add block</button></form><select className="admin-search-input" value={blockId} onChange={event => setBlockId(event.target.value)}><option value="">Select block for flat</option>{blocks.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select><form className="quick-product-form" onSubmit={addFlat}><input value={flatNumber} onChange={event => setFlatNumber(event.target.value)} placeholder="Flat number" required /><button className="primary-button" disabled={!token || !blockId}>Add flat</button></form>{message && <small className="dashboard-message">{message}</small>}</section>;
}

function AdminRoleControls() {
  const [token, setToken] = useState(null); const [users, setUsers] = useState([]); const [userId, setUserId] = useState(''); const [role, setRole] = useState('APARTMENT_SELLER'); const [message, setMessage] = useState('');
  useEffect(() => { getAdminPortalToken().then(async nextToken => { setToken(nextToken); const data = await fetch(`${API_BASE}/admin/users`, { headers: { Authorization: `Bearer ${nextToken}` } }).then(response => response.json()); setUsers(Array.isArray(data) ? data : []); }).catch(() => setMessage('Unable to load users.')); }, []);
  async function updateRole(event) { event.preventDefault(); const user = users.find(item => item.id === userId); if (!user) return; const roles = role === 'CUSTOMER' ? ['CUSTOMER'] : role === 'GLOBAL_ADMIN' ? ['GLOBAL_ADMIN'] : ['CUSTOMER', role]; const response = await fetch(`${API_BASE}/admin/users/${userId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ roles }) }); const data = await response.json(); if (response.ok) { setUsers(current => current.map(item => item.id === userId ? data : item)); setMessage(`${user.name || user.phone} is now ${role}.`); } else setMessage(data.error?.message || 'Unable to update user role.'); }
  return <section className="dashboard-panel admin-resource-panel"><div className="panel-heading"><div><p className="eyebrow">USER ROLE MANAGEMENT</p><h2>Mark a user as seller</h2></div><span className="menu-count">{users.length} users</span></div><form className="quick-product-form" onSubmit={updateRole}><select value={userId} onChange={event => setUserId(event.target.value)}><option value="">Select user</option>{users.map(user => <option value={user.id} key={user.id}>{user.name || 'Unnamed'} · {user.phone}</option>)}</select><select value={role} onChange={event => setRole(event.target.value)}><option value="APARTMENT_SELLER">Apartment seller</option><option value="OUTSIDE_SELLER">Outside seller</option><option value="DELIVERY_BOY">Delivery boy</option><option value="CUSTOMER">Customer</option></select><button className="primary-button" disabled={!token || !userId}>Save role</button></form>{message && <small className="dashboard-message">{message}</small>}</section>;
}

